/**
 * Core ServiceMediaGallery Component
 * Provides low-level access to service media gallery items via render props
 */
import React from 'react';
/**
 * Media item type for gallery items
 */
export interface MediaItem {
    image?: string;
}
/**
 * Render props for MediaGallery component
 */
export interface MediaGalleryRenderProps {
    /** Array of media items in the gallery */
    mediaItems: MediaItem[];
    /** Whether the service has any media items */
    hasMediaItems: boolean;
}
/**
 * Props for MediaGallery component
 */
export interface MediaGalleryProps {
    /** Render prop function that receives media gallery data */
    children: (props: MediaGalleryRenderProps) => React.ReactNode;
}
/**
 * Core component that provides access to service media gallery items via render props.
 * Must be used within a Service.Root context.
 *
 * @component
 * @example
 * ```tsx
 * <ServiceMediaGallery.MediaGallery>
 *   {({ mediaItems, hasMediaItems }) => (
 *     hasMediaItems ? (
 *       <div>
 *         {mediaItems.map((item, index) => (
 *           <img key={index} src={item.image} alt={`Gallery item ${index}`} />
 *         ))}
 *       </div>
 *     ) : (
 *       <div>No gallery items available</div>
 *     )
 *   )}
 * </ServiceMediaGallery.MediaGallery>
 * ```
 */
export declare function MediaGallery(props: MediaGalleryProps): React.ReactNode;
